import { BrowserRouter, Link, Outlet, Route, Routes, useParams } from "react-router";

const projects: Record<string, string> = { atlas: "Atlas", beacon: "Beacon" };

function ProjectsLayout() {
  return <main><h1>Projects</h1><Outlet /></main>;
}

function ProjectList() {
  return <p><Link to="atlas">Open Atlas</Link></p>;
}

function ProjectPage() {
  const { projectId } = useParams<{ projectId: string }>();
  const name = projectId ? projects[projectId] : undefined;
  if (!name) return <h2>Project not found</h2>;
  return <h2>{name}</h2>;
}

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="projects" element={<ProjectsLayout />}>
          <Route index element={<ProjectList />} />
          <Route path=":projectId" element={<ProjectPage />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}
